const code=`# Boundary searches use a half-open candidate range [lo, hi).
import bisect

def lower_bound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upper_bound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo

nums = [1, 2, 2, 2, 3, 5]
print(lower_bound(nums, 2))
print(upper_bound(nums, 2))`;
